/**
 * sitemap.xml and robots.txt, generated by the SSR server from the live catalog so they never go
 * stale. Pages that need a session or are a step of checkout are kept out of search engines.
 */

const PUBLIC_PAGES = ['/', '/sobre-nosotros', '/contacto', '/aviso-privacidad'];

const PRIVATE_PATHS = [
  '/admin', '/checkout', '/cart', '/confirmacion', '/orders', '/profile',
  '/login', '/register', '/forgot-password', '/reset-password', '/unsubscribe', '/rastrear-pedido',
];

const PAGE_SIZE = 100;
const MAX_PAGES = 50; // 5,000 products: far beyond the store, and a bound on a bad API answer

interface ProductPage {
  content: { slug: string; createdAt?: string }[];
  last: boolean;
}

/** Every active product's slug, page by page from the public catalog API. */
export async function fetchProductSlugs(apiOrigin: string, fetchFn: typeof fetch = fetch): Promise<{ slug: string; createdAt?: string }[]> {
  const products: { slug: string; createdAt?: string }[] = [];
  for (let page = 0; page < MAX_PAGES; page++) {
    const res = await fetchFn(`${apiOrigin}/api/products?page=${page}&size=${PAGE_SIZE}`, {
      signal: AbortSignal.timeout(10_000),
    });
    if (!res.ok) throw new Error(`catalog API answered ${res.status}`);
    const data = ((await res.json()) as { data: ProductPage }).data;
    products.push(...data.content);
    if (data.last || data.content.length === 0) break;
  }
  return products;
}

export function sitemapXml(siteOrigin: string, products: { slug: string; createdAt?: string }[]): string {
  const url = (path: string, lastmod?: string) =>
    `  <url><loc>${escapeXml(siteOrigin + path)}</loc>${lastmod ? `<lastmod>${lastmod.slice(0, 10)}</lastmod>` : ''}</url>`;
  return [
    '<?xml version="1.0" encoding="UTF-8"?>',
    '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
    ...PUBLIC_PAGES.map(path => url(path)),
    ...products.map(p => url(`/products/${encodeURIComponent(p.slug)}`, p.createdAt)),
    '</urlset>',
    '',
  ].join('\n');
}

export function robotsTxt(siteOrigin: string): string {
  return [
    'User-agent: *',
    ...PRIVATE_PATHS.map(path => `Disallow: ${path}`),
    '',
    `Sitemap: ${siteOrigin}/sitemap.xml`,
    '',
  ].join('\n');
}

function escapeXml(text: string): string {
  return text.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&apos;');
}
